  UNION ALL SELECT 6 AS sort_order, 'OBJETOS INVALIDOS' AS verificacao, '=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM all_objects WHERE owner = 'OPENRISOW' AND status = 'INVALID' AND object_name IN ('SSDEV_ENVIRONMENTS', 'SSDEV_PROFILES', 'SSDEV_FEATURES', 'SSDEV_PROFILE_FEATURE', 'SSDEV_PROFILE_ENV', 'SSDEV_SCRIPTS',
      'SSDEV_PROFILE_SCRIPT', 'SSDEV_SCRIPT_ENV', 'SSDEV_USERS', 'SSDEV_PARAMETERS', 'SSDEV_SCRIPT_PARAM', 'SSDEV_SCHEDULES',
      'SSDEV_TICKETS', 'SSDEV_TICKET_ANSWER', 'SSDEV_AGENTS', 'SSDEV_AUDIT', 'SSDEV_CONTROL', 'SSDEV_TICKET_OUTPUT',
      'SSDEV_INPUT_UPLOAD', 'SSDEV_INPUT_DELIVERY', 'SSDEV_INPUT_LISTING', 'SQ_SSDEV_ENVIRONMENTS', 'SQ_SSDEV_PROFILES', 'SQ_SSDEV_FEATURES',
      'SQ_SSDEV_PROFILE_FEATURE', 'SQ_SSDEV_PROFILE_ENV', 'SQ_SSDEV_SCRIPTS', 'SQ_SSDEV_PROFILE_SCRIPT', 'SQ_SSDEV_SCRIPT_ENV', 'SQ_SSDEV_USERS',
      'SQ_SSDEV_PARAMETERS', 'SQ_SSDEV_SCRIPT_PARAM', 'SQ_SSDEV_SCHEDULES', 'SQ_SSDEV_TICKETS', 'SQ_SSDEV_TICKET_ANSWER', 'SQ_SSDEV_AGENTS',
      'SQ_SSDEV_AUDIT', 'SQ_SSDEV_CONTROL', 'SQ_SSDEV_TICKET_OUTPUT', 'SQ_SSDEV_INPUT_UPLOAD', 'SQ_SSDEV_INPUT_DELIVERY', 'SQ_SSDEV_INPUT_LISTING',
      'TR_SSDEV_ENV_BI', 'TR_SSDEV_ENV_BU', 'TR_SSDEV_PRF_BI', 'TR_SSDEV_FEA_BI', 'TR_SSDEV_PFEA_BI', 'TR_SSDEV_PENV_BI',
      'TR_SSDEV_SCR_BI', 'TR_SSDEV_PSCR_BI', 'TR_SSDEV_SENV_BI', 'TR_SSDEV_USR_BI', 'TR_SSDEV_USR_BU', 'TR_SSDEV_PRM_BI',
      'TR_SSDEV_SPRM_BI', 'TR_SSDEV_SCH_BI', 'TR_SSDEV_TCK_BI', 'TR_SSDEV_TANS_BI', 'TR_SSDEV_AGT_BI', 'TR_SSDEV_AUD_BI',
      'TR_SSDEV_CTL_BI', 'TR_SSDEV_TOUT_BI', 'TR_SSDEV_IUP_BI', 'TR_SSDEV_IDL_BI', 'TR_SSDEV_ILS_BI', 'IX_SSDEV_PFEA_FEA',
      'IX_SSDEV_PENV_ENV', 'IX_SSDEV_PSCR_SCR', 'IX_SSDEV_SENV_ENV', 'IX_SSDEV_USR_PRF', 'IX_SSDEV_SPRM_PRM', 'IX_SSDEV_SCH_SCR',
      'IX_SSDEV_SCH_USR', 'IX_SSDEV_SCH_ENV', 'IX_SSDEV_SCH_NEXT', 'IX_SSDEV_TCK_SCR', 'IX_SSDEV_TCK_ENV', 'IX_SSDEV_TCK_USR',
      'IX_SSDEV_TCK_PAR', 'IX_SSDEV_TCK_SCH', 'IX_SSDEV_TCK_CRT', 'IX_SSDEV_TCK_HIST', 'IX_SSDEV_TCK_QUEUE', 'IX_SSDEV_TCK_RUN',
      'IX_SSDEV_TCK_OCCUR', 'IX_SSDEV_TANS_PRM', 'IX_SSDEV_AUD_CRT', 'IX_SSDEV_AUD_ENT', 'IX_SSDEV_AUD_ACTOR', 'IX_SSDEV_TOUT_WRITE',
      'IX_SSDEV_IUP_ENV', 'IX_SSDEV_IUP_SCR', 'IX_SSDEV_IUP_CRT', 'IX_SSDEV_IDL_PEND', 'IX_SSDEV_ILS_ENV', 'IX_SSDEV_ILS_SCR')) AS encontrado FROM DUAL
  UNION ALL SELECT 7 AS sort_order, 'GRANTS A PUBLIC' AS verificacao, '=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM all_tab_privs WHERE table_schema = 'OPENRISOW' AND grantee = 'PUBLIC' AND table_name IN ('SSDEV_ENVIRONMENTS', 'SSDEV_PROFILES', 'SSDEV_FEATURES', 'SSDEV_PROFILE_FEATURE', 'SSDEV_PROFILE_ENV', 'SSDEV_SCRIPTS',
      'SSDEV_PROFILE_SCRIPT', 'SSDEV_SCRIPT_ENV', 'SSDEV_USERS', 'SSDEV_PARAMETERS', 'SSDEV_SCRIPT_PARAM', 'SSDEV_SCHEDULES',
      'SSDEV_TICKETS', 'SSDEV_TICKET_ANSWER', 'SSDEV_AGENTS', 'SSDEV_AUDIT', 'SSDEV_CONTROL', 'SSDEV_TICKET_OUTPUT',
      'SSDEV_INPUT_UPLOAD', 'SSDEV_INPUT_DELIVERY', 'SSDEV_INPUT_LISTING', 'SQ_SSDEV_ENVIRONMENTS', 'SQ_SSDEV_PROFILES', 'SQ_SSDEV_FEATURES',
      'SQ_SSDEV_PROFILE_FEATURE', 'SQ_SSDEV_PROFILE_ENV', 'SQ_SSDEV_SCRIPTS', 'SQ_SSDEV_PROFILE_SCRIPT', 'SQ_SSDEV_SCRIPT_ENV', 'SQ_SSDEV_USERS',
      'SQ_SSDEV_PARAMETERS', 'SQ_SSDEV_SCRIPT_PARAM', 'SQ_SSDEV_SCHEDULES', 'SQ_SSDEV_TICKETS', 'SQ_SSDEV_TICKET_ANSWER', 'SQ_SSDEV_AGENTS',
      'SQ_SSDEV_AUDIT', 'SQ_SSDEV_CONTROL', 'SQ_SSDEV_TICKET_OUTPUT', 'SQ_SSDEV_INPUT_UPLOAD', 'SQ_SSDEV_INPUT_DELIVERY', 'SQ_SSDEV_INPUT_LISTING')) AS encontrado FROM DUAL
)
SELECT CASE WHEN COUNT(*) = 0 THEN 'OK: nenhuma falha'
            ELSE 'FALHA: ' || COUNT(*) || ' verificacao(oes) divergente(s)' END AS resumo
  FROM chk
 WHERE NOT ((regra = '=' AND encontrado = esperado) OR (regra = '>=' AND encontrado >= esperado))
    OR encontrado IS NULL;

PROMPT ==============================================================================
PROMPT 2. VERSAO DO ESQUEMA E MINIMO DE LINHAS DO SEED
PROMPT (se as tabelas nao existirem, esta secao falha com ORA-00942: veja a secao 1)
PROMPT ==============================================================================
WITH chk AS (
  SELECT 10 AS sort_order, 'VERSAO DO ESQUEMA' AS verificacao, '=' AS regra, 1 AS esperado, (SELECT MAX(schema_version) FROM openrisow.ssdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 11 AS sort_order, 'LINHAS SSDEV_ENVIRONMENTS' AS verificacao, '>=' AS regra, 5 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_environments) AS encontrado FROM DUAL
  UNION ALL SELECT 12 AS sort_order, 'LINHAS SSDEV_PROFILES' AS verificacao, '>=' AS regra, 4 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profiles) AS encontrado FROM DUAL
  UNION ALL SELECT 13 AS sort_order, 'LINHAS SSDEV_FEATURES' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_features) AS encontrado FROM DUAL
  UNION ALL SELECT 14 AS sort_order, 'LINHAS SSDEV_PROFILE_FEATURE' AS verificacao, '>=' AS regra, 29 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profile_feature) AS encontrado FROM DUAL
  UNION ALL SELECT 15 AS sort_order, 'LINHAS SSDEV_PROFILE_ENV' AS verificacao, '>=' AS regra, 18 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profile_env) AS encontrado FROM DUAL
  UNION ALL SELECT 16 AS sort_order, 'LINHAS SSDEV_SCRIPTS' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_scripts) AS encontrado FROM DUAL
  UNION ALL SELECT 17 AS sort_order, 'LINHAS SSDEV_PROFILE_SCRIPT' AS verificacao, '>=' AS regra, 56 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profile_script) AS encontrado FROM DUAL
  UNION ALL SELECT 18 AS sort_order, 'LINHAS SSDEV_SCRIPT_ENV' AS verificacao, '>=' AS regra, 70 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_script_env) AS encontrado FROM DUAL
  UNION ALL SELECT 19 AS sort_order, 'LINHAS SSDEV_USERS' AS verificacao, '>=' AS regra, 4 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_users) AS encontrado FROM DUAL
  UNION ALL SELECT 20 AS sort_order, 'LINHAS SSDEV_PARAMETERS' AS verificacao, '>=' AS regra, 19 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_parameters) AS encontrado FROM DUAL
  UNION ALL SELECT 21 AS sort_order, 'LINHAS SSDEV_SCRIPT_PARAM' AS verificacao, '>=' AS regra, 38 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_script_param) AS encontrado FROM DUAL
  UNION ALL SELECT 22 AS sort_order, 'LINHAS SSDEV_SCHEDULES' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_schedules) AS encontrado FROM DUAL
  UNION ALL SELECT 23 AS sort_order, 'LINHAS SSDEV_TICKETS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_tickets) AS encontrado FROM DUAL
  UNION ALL SELECT 24 AS sort_order, 'LINHAS SSDEV_TICKET_ANSWER' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_ticket_answer) AS encontrado FROM DUAL
  UNION ALL SELECT 25 AS sort_order, 'LINHAS SSDEV_AGENTS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_agents) AS encontrado FROM DUAL
  UNION ALL SELECT 26 AS sort_order, 'LINHAS SSDEV_AUDIT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_audit) AS encontrado FROM DUAL
  UNION ALL SELECT 27 AS sort_order, 'LINHAS SSDEV_CONTROL' AS verificacao, '>=' AS regra, 1 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 28 AS sort_order, 'LINHAS SSDEV_TICKET_OUTPUT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_ticket_output) AS encontrado FROM DUAL
  UNION ALL SELECT 29 AS sort_order, 'LINHAS SSDEV_INPUT_UPLOAD' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_input_upload) AS encontrado FROM DUAL
  UNION ALL SELECT 30 AS sort_order, 'LINHAS SSDEV_INPUT_DELIVERY' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_input_delivery) AS encontrado FROM DUAL
  UNION ALL SELECT 31 AS sort_order, 'LINHAS SSDEV_INPUT_LISTING' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_input_listing) AS encontrado FROM DUAL
)
SELECT verificacao, regra || ' ' || esperado AS esperado, encontrado,
       CASE WHEN (regra = '=' AND encontrado = esperado) OR (regra = '>=' AND encontrado >= esperado)
            THEN 'OK' ELSE 'FALHA' END AS resultado
  FROM chk ORDER BY sort_order;

WITH chk AS (
  SELECT 10 AS sort_order, 'VERSAO DO ESQUEMA' AS verificacao, '=' AS regra, 1 AS esperado, (SELECT MAX(schema_version) FROM openrisow.ssdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 11 AS sort_order, 'LINHAS SSDEV_ENVIRONMENTS' AS verificacao, '>=' AS regra, 5 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_environments) AS encontrado FROM DUAL
  UNION ALL SELECT 12 AS sort_order, 'LINHAS SSDEV_PROFILES' AS verificacao, '>=' AS regra, 4 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profiles) AS encontrado FROM DUAL
  UNION ALL SELECT 13 AS sort_order, 'LINHAS SSDEV_FEATURES' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_features) AS encontrado FROM DUAL
  UNION ALL SELECT 14 AS sort_order, 'LINHAS SSDEV_PROFILE_FEATURE' AS verificacao, '>=' AS regra, 29 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profile_feature) AS encontrado FROM DUAL
  UNION ALL SELECT 15 AS sort_order, 'LINHAS SSDEV_PROFILE_ENV' AS verificacao, '>=' AS regra, 18 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profile_env) AS encontrado FROM DUAL
  UNION ALL SELECT 16 AS sort_order, 'LINHAS SSDEV_SCRIPTS' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_scripts) AS encontrado FROM DUAL
  UNION ALL SELECT 17 AS sort_order, 'LINHAS SSDEV_PROFILE_SCRIPT' AS verificacao, '>=' AS regra, 56 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_profile_script) AS encontrado FROM DUAL
  UNION ALL SELECT 18 AS sort_order, 'LINHAS SSDEV_SCRIPT_ENV' AS verificacao, '>=' AS regra, 70 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_script_env) AS encontrado FROM DUAL
  UNION ALL SELECT 19 AS sort_order, 'LINHAS SSDEV_USERS' AS verificacao, '>=' AS regra, 4 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_users) AS encontrado FROM DUAL
  UNION ALL SELECT 20 AS sort_order, 'LINHAS SSDEV_PARAMETERS' AS verificacao, '>=' AS regra, 19 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_parameters) AS encontrado FROM DUAL
  UNION ALL SELECT 21 AS sort_order, 'LINHAS SSDEV_SCRIPT_PARAM' AS verificacao, '>=' AS regra, 38 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_script_param) AS encontrado FROM DUAL
  UNION ALL SELECT 22 AS sort_order, 'LINHAS SSDEV_SCHEDULES' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_schedules) AS encontrado FROM DUAL
  UNION ALL SELECT 23 AS sort_order, 'LINHAS SSDEV_TICKETS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_tickets) AS encontrado FROM DUAL
  UNION ALL SELECT 24 AS sort_order, 'LINHAS SSDEV_TICKET_ANSWER' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_ticket_answer) AS encontrado FROM DUAL
  UNION ALL SELECT 25 AS sort_order, 'LINHAS SSDEV_AGENTS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_agents) AS encontrado FROM DUAL
  UNION ALL SELECT 26 AS sort_order, 'LINHAS SSDEV_AUDIT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_audit) AS encontrado FROM DUAL
  UNION ALL SELECT 27 AS sort_order, 'LINHAS SSDEV_CONTROL' AS verificacao, '>=' AS regra, 1 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 28 AS sort_order, 'LINHAS SSDEV_TICKET_OUTPUT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_ticket_output) AS encontrado FROM DUAL
  UNION ALL SELECT 29 AS sort_order, 'LINHAS SSDEV_INPUT_UPLOAD' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_input_upload) AS encontrado FROM DUAL
  UNION ALL SELECT 30 AS sort_order, 'LINHAS SSDEV_INPUT_DELIVERY' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_input_delivery) AS encontrado FROM DUAL
  UNION ALL SELECT 31 AS sort_order, 'LINHAS SSDEV_INPUT_LISTING' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.ssdev_input_listing) AS encontrado FROM DUAL
)
SELECT CASE WHEN COUNT(*) = 0 THEN 'OK: nenhuma falha'
            ELSE 'FALHA: ' || COUNT(*) || ' verificacao(oes) divergente(s)' END AS resumo
  FROM chk
 WHERE NOT ((regra = '=' AND encontrado = esperado) OR (regra = '>=' AND encontrado >= esperado))
    OR encontrado IS NULL;

PROMPT ==============================================================================
PROMPT 3. USUARIOS E PERFIS (sem hash de senha)
PROMPT ==============================================================================
COLUMN login FORMAT A20
COLUMN name FORMAT A30
COLUMN perfil FORMAT A20
COLUMN admin FORMAT A5
COLUMN active FORMAT A5
COLUMN senha_definida FORMAT A14
SELECT u.id, u.login, u.name, p.name AS perfil, p.is_admin AS admin, u.active,
       CASE WHEN u.password_hash IS NULL THEN 'N' ELSE 'Y' END AS senha_definida
  FROM openrisow.ssdev_users u JOIN openrisow.ssdev_profiles p ON p.id = u.profile_id
 ORDER BY u.id;

PROMPT ==============================================================================
PROMPT 4. SCRIPTS CADASTRADOS
PROMPT ==============================================================================
COLUMN name FORMAT A25
COLUMN interpreter FORMAT A13
COLUMN param_type FORMAT A10
COLUMN path_file FORMAT A70
SELECT id, name, interpreter, param_type, max_parallel_env AS paral, timeout_s AS tmout,
       active, path_file
  FROM openrisow.ssdev_scripts
 ORDER BY id;

PROMPT ==============================================================================
PROMPT 5. ACESSO POR PERFIL (funcionalidades, ambientes e scripts liberados)
PROMPT ==============================================================================
COLUMN perfil FORMAT A20
SELECT p.name AS perfil, p.is_admin AS admin, p.active,
       (SELECT COUNT(*) FROM openrisow.ssdev_profile_feature x WHERE x.profile_id = p.id) AS funcionalidades,
       (SELECT COUNT(*) FROM openrisow.ssdev_profile_env x WHERE x.profile_id = p.id) AS environments,
       (SELECT COUNT(*) FROM openrisow.ssdev_profile_script x WHERE x.profile_id = p.id) AS scripts
  FROM openrisow.ssdev_profiles p
 ORDER BY p.name;

PROMPT ==============================================================================
PROMPT 6. GRANTS NOS OBJETOS DO SSS (README 11.1: so contas dos papeis; nunca PUBLIC)
PROMPT ==============================================================================
SET FEEDBACK ON
COLUMN grantee FORMAT A30
COLUMN privilege FORMAT A12
SELECT grantee, privilege, COUNT(*) AS objetos
  FROM all_tab_privs
 WHERE table_schema = 'OPENRISOW' AND table_name IN ('SSDEV_ENVIRONMENTS', 'SSDEV_PROFILES', 'SSDEV_FEATURES', 'SSDEV_PROFILE_FEATURE', 'SSDEV_PROFILE_ENV', 'SSDEV_SCRIPTS',
      'SSDEV_PROFILE_SCRIPT', 'SSDEV_SCRIPT_ENV', 'SSDEV_USERS', 'SSDEV_PARAMETERS', 'SSDEV_SCRIPT_PARAM', 'SSDEV_SCHEDULES',
      'SSDEV_TICKETS', 'SSDEV_TICKET_ANSWER', 'SSDEV_AGENTS', 'SSDEV_AUDIT', 'SSDEV_CONTROL', 'SSDEV_TICKET_OUTPUT',
      'SSDEV_INPUT_UPLOAD', 'SSDEV_INPUT_DELIVERY', 'SSDEV_INPUT_LISTING', 'SQ_SSDEV_ENVIRONMENTS', 'SQ_SSDEV_PROFILES', 'SQ_SSDEV_FEATURES',
      'SQ_SSDEV_PROFILE_FEATURE', 'SQ_SSDEV_PROFILE_ENV', 'SQ_SSDEV_SCRIPTS', 'SQ_SSDEV_PROFILE_SCRIPT', 'SQ_SSDEV_SCRIPT_ENV', 'SQ_SSDEV_USERS',
      'SQ_SSDEV_PARAMETERS', 'SQ_SSDEV_SCRIPT_PARAM', 'SQ_SSDEV_SCHEDULES', 'SQ_SSDEV_TICKETS', 'SQ_SSDEV_TICKET_ANSWER', 'SQ_SSDEV_AGENTS',
      'SQ_SSDEV_AUDIT', 'SQ_SSDEV_CONTROL', 'SQ_SSDEV_TICKET_OUTPUT', 'SQ_SSDEV_INPUT_UPLOAD', 'SQ_SSDEV_INPUT_DELIVERY', 'SQ_SSDEV_INPUT_LISTING')
 GROUP BY grantee, privilege
 ORDER BY grantee, privilege;
SET FEEDBACK OFF

PROMPT Fim da validacao do SSS.
EXIT;
